"""Opt-in removal of a publication's generated files, never its input resources."""
from __future__ import annotations

import stat
from pathlib import Path

from .jobs import fingerprint


def inventory(root: Path, sources: list[Path], files: list[dict], enabled: bool) -> dict:
    return {"enabled": bool(enabled), "root": str(root.resolve()),
            "sources": [str(p.resolve()) for p in sources],
            "files": [{**rec, "state": "pending"} for rec in files], "state": "pending"}


def register(plan: dict, record: dict) -> None:
    """Only call at generation time, before the new payload can be uploaded."""
    cleanup = plan.get("local_cleanup")
    if cleanup is None:
        return
    items = cleanup["files"]
    old = next((item for item in items if item["path"] == record["path"]), None)
    if old is None:
        items.append({**record, "state": "pending"})
    else:
        old.update(record, state="pending")
        old.pop("reason", None)


def owns(plan: dict, record: dict) -> bool:
    """A shared file may be absent on replay only when it was generated by this job."""
    cleanup = plan.get("local_cleanup") or {}
    return bool(cleanup.get("enabled") and any(
        all(item.get(k) == record.get(k) for k in ("path", "size", "sha256"))
        for item in cleanup.get("files", [])))


def summary(plan: dict) -> dict:
    cleanup = plan.get("local_cleanup") or {}
    items = cleanup.get("files", [])
    return {"enabled": bool(cleanup.get("enabled")), "state": cleanup.get("state", "pending"),
            "deleted": sum(item.get("state") == "deleted" for item in items),
            "retained": sum(item.get("state") not in ("deleted", "missing") for item in items),
            "bytes": sum(item["size"] for item in items if item.get("state") == "deleted")}


def _safe_path(root: Path, item: dict, sources: list[Path]) -> Path:
    path = Path(item["path"])
    # No recursive deletion, globs, external paths, or directory-link traversal.
    relative = path.relative_to(root)
    if not relative.parts or ".." in relative.parts:
        raise ValueError("outside_task")
    if not (len(relative.parts) == 2 and relative.parts[0] == "body" or
            len(relative.parts) == 1 and relative.name in ("guide.txt", "guide.7z")):
        raise ValueError("not_generated_payload")
    for candidate in (root, *reversed(path.parents[:len(relative.parts) - 1]), path):
        if candidate.is_symlink() or (candidate.exists() and
                getattr(candidate.lstat(), "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT):
            raise ValueError("linked_path")
    resolved = path.resolve()
    if not resolved.is_relative_to(root):
        raise ValueError("outside_task")
    if path.exists() and path.stat().st_nlink > 1:
        raise ValueError("linked_file")
    for source in sources:
        if resolved == source or source in resolved.parents:
            raise ValueError("source_resource")
        if source.is_file() and path.exists() and path.samefile(source):
            raise ValueError("source_resource")
    return path


def remove_generated(plan_path: Path, plan: dict, checkpoint, notify=print) -> None:
    """Run only after every stage is confirmed uploaded/shared and copy is durable.

    Per-file checkpoints allow a completed task to retry a Windows file lock without
    uploading again. A cleanup failure must not turn a successful share into failure.
    """
    cleanup = plan.get("local_cleanup") or {}
    if not cleanup.get("enabled"):
        return
    if plan.get("state") != "complete" or not plan.get("stages") or any(
        not stage.get("share") or not stage.get("files") or
        any(rec["path"] not in stage.get("uploaded", {}) for rec in stage["files"])
        for stage in plan["stages"]
    ):
        cleanup["state"] = "retained"
        checkpoint()
        notify("未自动清理：尚未确认所有文件上传并分享成功；本地产物保留")
        return
    root = plan_path.parent.resolve()
    if cleanup.get("root") != str(root):
        cleanup["state"] = "retained"
        checkpoint()
        notify("未自动清理：任务目录已移动；本地产物保留")
        return
    sources = [Path(p).resolve() for p in cleanup.get("sources", [])]
    cleanup["state"] = "running"
    checkpoint()
    for item in cleanup.get("files", []):
        if item.get("state") == "deleted":
            continue
        try:
            path = _safe_path(root, item, sources)
            if not path.exists():
                item["state"] = "missing"
            elif not path.is_file() or fingerprint(path) != {k: item[k] for k in ("path", "size", "sha256")}:
                item.update(state="retained", reason="changed")
            else:
                # Each exact path is an owned, unchanged output. Never remove its folder.
                path.unlink()
                item["state"] = "deleted"
                item.pop("reason", None)
        except (OSError, ValueError) as exc:
            item.update(state="retained", reason=type(exc).__name__)
        checkpoint()
    cleanup["state"] = "partial" if summary(plan)["retained"] else "complete"
    checkpoint()
    result = summary(plan)
    notify(f"本地产物清理：已删除 {result['deleted']} 个加工文件，保留 {result['retained']} 个；源文件保留")
